import { statesOf, type Machine } from "./machine";

export const STATECHARTS_HEADER = [
  "# State charts",
  "",
  "Generated by `npm run docs:statecharts` from the transition tables in `src/domain/state/*.machine.ts`. Do not edit by hand. CI fails when this file is stale.",
  "",
].join("\n");

function label(event: string, guard: string | undefined): string {
  return guard ? `${event} [${guard}]` : event;
}

export function renderMachine(m: Machine<string, string>): string {
  const lines = ["```mermaid", "stateDiagram-v2", `  [*] --> ${m.initial}`];
  for (const t of m.transitions) lines.push(`  ${t.from} --> ${t.to}: ${label(t.event, t.guard)}`);
  for (const final of m.finals) lines.push(`  ${final} --> [*]`);
  const mentioned = new Set(m.transitions.flatMap((t) => [t.from, t.to]));
  for (const s of statesOf(m)) if (!mentioned.has(s) && s !== m.initial) lines.push(`  ${s}`);
  lines.push("```");
  return lines.join("\n");
}

export function renderDocument(machines: readonly Machine<string, string>[]): string {
  const sorted = [...machines].sort((a, b) => a.name.localeCompare(b.name));
  const sections = sorted.map((m) => [`## ${m.title}`, "", `Machine: \`${m.name}\``, "", renderMachine(m), ""].join("\n"));
  return `${STATECHARTS_HEADER}\n${sections.join("\n")}`;
}
